"""Import exactly 100 verified V3 model sheets into the off-Sunny-web catalog.
Read-only source extraction; no Excel application automation or source modification.
Run from repository root with --source <V3 folder> --selection <manifest JSON>
--output <staged JSON>. Optional --cache accepts a verified extraction JSON.
Fresh source reads use Python stdlib for XLSX/DOCX, xlrd for XLS, pypdf for PDF.
The cache is generated by the read-only batch extraction workflow, and file SHA-256
and cell references are recorded in the resulting audit. Existing records are never
rewritten. --output is intentionally required to review the staged batch first.
"""
import argparse,ast,hashlib,json,pathlib,re
ROOT=pathlib.Path(__file__).resolve().parents[1]
N=lambda s:re.sub(r'[^a-z0-9]','',str(s).lower())
MODEL=lambda s:re.sub(r'[^A-Z0-9]','',str(s).upper())
# Only public product fields are mapped; supplier/contact/cost/part-reference rows
# and instruction columns are deliberately not part of the importer.
ALIASES={
'brand':['brand'],'materials':['materials','material'],'color':['color'],'productWeight':['net weight','product weight'],'shippingWeight':['gross weight','shipping weight'],'keyDimensions':['assembled dimensions','product dimensions','dimensions','assembled size'],'foldedDimensions':['folded dimensions','fold dimensions'],'shippingDimensions':['shipping dimensions','carton dimensions'],'footprint':['floor footprint coverage','floor footprint'],'maxUserHeight':['max user height'],'driveResistanceSystem':['drive mechanism','drive system','tension system'],'resistanceType':['resistance type','type of resistance'],'speedResistanceLevels':['levels of resistance','resistance level','level of resistance'],'flywheelWeight':['flywheel weight'],'inseam':['inseam range','inseam'],'qFactor':['q-factor'],'seatAdjustment':['fully adjustable seat','seat adjustment'],'handlebarAdjustment':['fully adjustable handlebar','handlebar adjustment'],'seatHeight':['seat height'],'seatToHandlebar':['seat to handlebar distance'],'pedalType':['pedal type','spd pedals'],'pedalThread':['pedal thread size'],'crankType':['type of crank','crank type'],'battery':['type of battery','meter battery used','battery type','battery'],'display':['meter displays','meter display','specific meter display','console feature','meter feature'],'screenType':['screen type','screen/display','meter screen/display type'],'screenSize':['screen size','screen/display size','meer screen/display size'],'deviceHolder':['device holder','tablet holder/rack','device/tablet holder'],'heartRate':['heart monitor/pulse sensors','hand pulse sensors','hand pulse sensor'],'wirelessHeartRate':['heart monitor/pulse wireless','wireless heart rate function'],'bluetooth':['bluetooth connectivity'],'foldable':['foldable','folding'],'transportWheels':['transportation wheel'],'bottleHolder':['hydration','water bottle holder'],'motorType':['motor type','type of motor'],'continuousHp':['motor horsepower continuous'],'peakHp':['motor horsepower peak'],'speedRange':['speed range'],'inclineType':['incline type'],'inclineRange':['incline % range'],'inclineLevels':['incline level'],'inclineDegrees':['incline angle degrees','incline degree range'],'runningSurface':['running space size','running surface measurement'],'beltDimensions':['running belt size','running belt measurement'],'softDrop':['soft drop'],'shockAbsorption':['shock absorption'],'electrical':['electrical requirement','voltage'],'watts':['watt'],'amps':['ampere'],'powerCord':['plug or adapter cord length','length of power cord'],'programs':['program','number of pre-programs'],'speakers':['speakers/audio','mp3/earphone jack'],'usb':['mobile charging','usb charging'],'stride':['stride length'],'seatDimensions':['seat dimensions'],'accessories':['accessory included'],'features':['features/functions/selling points of this product','features/funtions/selling points of this product','features','please list all other special features'],'upc':['upc'],'latex':['contain latex','contained latex','container latex/rubber'],'maxUserWeightLb':['max user weight','maximum user weight'],'certification':['tests done for this item','tests certification','certification'],'magnets':['magnets'],'crankLength':['crank length'],'ftms':['ftms'],'wifi':['wifi'],'plugType':['plug type'],'stepHeight':['step height'],'resistanceBands':['resistance bands'],'handrail':['handrail'],'pedalDimensions':['pedal dimensions'],'capacityConditions':['max weight capacity'],'weightOptions':['weight range','weight options'],'adjustments':['adjustment positions']}
EMPTY={'','-','--','tbd','tobeconfirmed','detail','minmax','peakcontinuous','measured based on our typical way','noneprovided'}
INSTRUCTION=re.compile(r'insert.*(?:picture|image)|if.*whole number|must list|need to have|please.*provide|vertically or horizontally|single or double|brushless\?',re.I)
def clean(value):
 value=' '.join(str(value).split()).strip()
 if N(value)in {'na','notapplicable'}:return 'Not applicable'
 if value.lower()in EMPTY or N(value)in {'min','max','minmax','peak','continuous','peakcontinuous','batt','detail','battery','pending','tbc','tbd','mm','cm','inches','inch','lbs','kg','kgs','v','a'}or INSTRUCTION.search(value):return None
 if re.search(r'if yes|or others|check.*(?:right|data)|please see|select.*type',value,re.I):return None
 value=re.sub(r'^Detail:\s*','',value,flags=re.I)
 if value.startswith(('#VALUE!','#DIV/0!')):return None
 # Keep a supplied English translation instead of both duplicated language blocks.
 if re.search(r'[\u4e00-\u9fff]',value):
  m=re.search(r'\b1\s*[,，.、]\s*(?=[A-Za-z])',value)
  if m:value=value[m.start():]
 if re.search(r'[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}',value,re.I):return None
 return value

def pairs(sheet,cat=None,name=''):
 out=[];section=None
 headers={'bike':'bike','ellipticalstepperminicycle':'mini','recumbentbike':'recumbent','treadmill':'treadmill','rower':'rower'}
 for row in sheet['rows']:
  label=N(row[0][1])
  if label in headers:section=headers[label];continue
  if label.startswith(('accessories','resistanceforce','mastercarton')):section=None
  if cat and section:
   allowed=({'bike','recumbent','mini'}if cat=='Indoor Bikes'and any(x in name.lower()for x in ['under desk','mini','pedal','portable'])else {'bike','recumbent'}if cat=='Indoor Bikes'else {'mini'}if cat in ['Ellipticals','Steppers']else {'rower'}if cat=='Rowers'else {'treadmill'}if cat=='Treadmills'else set())
   if section not in allowed:continue
  if len(row)<2:continue
  a=row[0];b=row[1];value=clean(b[1])
  if not value:continue
  # Source forms sometimes put a real answer in D when B is empty. Notes and
  # option prompts are filtered by clean; image/date cells are never aliases.
  if re.fullmatch(r'A\d+',a[0])and not re.fullmatch(r'[BD]\d+',b[0]):continue
  # MIN and MAX are separate cells on older forms. Preserve both actual limits.
  if re.match(r'^MIN\s*:',value,re.I):
   upper=next((clean(v)for addr,v in row[2:]if re.match(r'^MAX\s*:',v,re.I)and clean(v)),None)
   if upper:value+='; '+upper
  out.append((label,a[1],value,b[0]))
 return out

def match_sheet(sheets,sku):
 target=MODEL(sku);matches=[]
 for sheet in sheets:
  score=0;ev=None
  for row in sheet['rows']:
   for i,(addr,text)in enumerate(row):
    if N(text)in ['model','modelnumber','modelno','item','itemnumber','itemno','productmodel','productnumber']and i+1<len(row):
     val=row[i+1][1]
     if MODEL(val)==target:score=100;ev={'cell':row[i+1][0],'text':val};break
     if target in [MODEL(x)for x in re.split(r'[/,;]',val)]:score=90;ev={'cell':row[i+1][0],'text':val}
   if score==100:break
  if not score and MODEL(sheet['name'])==target:score=80;ev={'sheetName':sheet['name']}
  matches.append((score,len(pairs(sheet)),sheet,ev))
 matches.sort(key=lambda x:(x[0],x[1]),reverse=True)
 score,_,sheet,ev=matches[0]
 if not score and len(sheets)>1:raise ValueError('No exact-model sheet found: '+sku)
 return sheet,ev,score

def find(p,aliases):
 for alias in aliases:
  k=N(alias)
  for row in p:
   if k=='screendisplay'and'size'in row[0]:continue
   if row[0]==k or (row[0].startswith(k)and len(row[0])-len(k)<65):return row
 return None

def category(name,sku):
 s=name.lower()
 if 'row-n-ride'in s or 'row-n-ride'in s.replace('®','')or 'squat exercise trainer'in s:return 'Row-N-Ride'
 if any(t in s for t in ['elliptical','air walker']):return 'Ellipticals'
 if any(t in s for t in ['rowing','rower']):return 'Rowers'
 if 'aerobic stepper'in s:return 'Essentials'
 if any(t in s for t in ['stepper','step climber','step machine']):return 'Steppers'
 if any(t in s for t in ['bike','cycle','cycling']):return 'Indoor Bikes'
 if 'weight bench'in s:return 'Weight Benches'
 if 'power rack'in s:return 'Racks'
 if any(t in s for t in ['dumbbell','olympic','hex bar','trap bar']):return 'Weights'
 return 'Essentials'

def num_lb(text,label):
 if not text or text=='Not applicable':return None
 m=re.search(r'(\d+(?:\.\d+)?)\s*(?:lb|lbs|pound)',text,re.I)
 if m:return float(m[1])
 m=re.search(r'(\d+(?:\.\d+)?)\s*(?:kg|kgs|kilogram)',text,re.I)
 if m:return round(float(m[1])*2.20462262185,1)
 if re.fullmatch(r'\d+(?:\.\d+)?',text)and re.search('lbs?|pounds?',label,re.I):return float(text)
 return None

def read_sources(base,selections):
 import zipfile,xml.etree.ElementTree as E
 ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
 # Optional readers are loaded only for the legacy formats present in this batch.
 try:
  import xlrd
 except ImportError:
  xlrd=None
 try:
  from pypdf import PdfReader
 except ImportError:
  PdfReader=None
 out={}
 for name in dict.fromkeys(x['sourceFile']for x in selections):
  p=base/name;sheets=[]
  if p.suffix.lower()=='.xlsx':
   with zipfile.ZipFile(p)as z:
    shared=[''.join(x.itertext())for x in E.fromstring(z.read('xl/sharedStrings.xml'))]if'xl/sharedStrings.xml'in z.namelist()else[]
    rels={x.get('Id'):x.get('Target')for x in E.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
    for sheet in E.fromstring(z.read('xl/workbook.xml')).findall('m:sheets/m:sheet',ns):
     if sheet.get('state','visible')!='visible':continue
     target=rels[sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')];target=target.lstrip('/')if target.startswith('/')else'xl/'+target
     rows=[]
     for row in E.fromstring(z.read(target)).findall('.//m:row',ns):
      cells=[]
      for c in row.findall('m:c',ns):
       v=c.find('m:v',ns);inline=c.find('m:is',ns);value=v.text if v is not None else ''.join(inline.itertext())if inline is not None else''
       if c.get('t')=='s'and value:value=shared[int(value)]
       if value is not None and str(value).strip():cells.append([c.get('r'),str(value).strip()])
      if cells:rows.append(cells)
     sheets.append({'name':sheet.get('name'),'rows':rows})
  elif p.suffix.lower()=='.xls':
   b=xlrd.open_workbook(p)
   for sheet in b.sheets():
    if sheet.visibility:continue
    rows=[]
    for i in range(sheet.nrows):
     cells=[[xlrd.formula.colname(j)+str(i+1),str(sheet.cell_value(i,j)).strip()]for j in range(sheet.ncols)if str(sheet.cell_value(i,j)).strip()]
     if cells:rows.append(cells)
    sheets.append({'name':sheet.name,'rows':rows})
  elif p.suffix.lower()=='.docx':
   with zipfile.ZipFile(p)as z:
    root=E.fromstring(z.read('word/document.xml'));wn={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'};rows=[]
    for i,tr in enumerate(root.findall('.//w:tr',wn)):
     cells=[[str(i+1)+':'+str(j+1),''.join(c.itertext()).strip()]for j,c in enumerate(tr.findall('w:tc',wn))]
     if cells:rows.append(cells)
    sheets=[{'name':'document','rows':rows}]
  elif p.suffix.lower()=='.pdf':sheets=[{'name':'PDF','rows':[[['page'+str(i+1),page.extract_text()or'']]for i,page in enumerate(PdfReader(p).pages)]}]
  out[name]=sheets
 return out

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--source',required=True,type=pathlib.Path);ap.add_argument('--cache',type=pathlib.Path);ap.add_argument('--selection',required=True,type=pathlib.Path);ap.add_argument('--output',required=True,type=pathlib.Path);a=ap.parse_args()
 selections=json.loads(a.selection.read_text(encoding='utf-8'));extracted=json.loads(a.cache.read_text(encoding='utf-8'))if a.cache else read_sources(a.source,selections);assert len(selections)==100
 templates=json.loads((ROOT/'data/specifications/templates.json').read_text(encoding='utf-8'))
 # Extra aliases from exact template labels permit public fields newly added by the app.
 for sections in templates.values():
  for section in sections:
   for key,label in section['fields']:
    if key not in ALIASES:ALIASES[key]=[re.sub(r'\([^)]*\)','',label).strip()]
 old=[r for r in json.loads((ROOT/'data/off-sunny-web/items.json').read_text(encoding='utf-8'))if r.get('importBatch')!='v3-batch-3'];current=[r for p in(ROOT/'data').glob('*.json')for r in json.loads(p.read_text(encoding='utf-8'))];existing={MODEL(r['sku'])for r in old+current};out=[];audit=[]
 for selected in selections:
  sku=selected['sku'].upper();file=selected['sourceFile'];notes=[]
  sheets=extracted[file]
  if file.lower().endswith('.pdf'):
   text=sheets[0]['rows'][0][0][1];sheet=sheets[0];ev={'page':1,'text':'Item Number: No. 085'};score=100
   # This PDF uses a two-column layout whose extracted name is below the labels.
   assert sku=='NO. 085'and'3 in 1 Weighted PRO-Plyo Box'in text
   name='3 in 1 Weighted PRO-Plyo Box 30" 24" 20"'
   p=[('brand','Brand:','Sunny','page1'),('productweight','Net Weight:','55.7 lb','page1'),('shippingweight','Gross Weight:','55.7 lb','page1'),('keydimensions','Product Dimensions:','30 × 24 × 20 (source does not label units)','page1'),('shippingdimensions','Carton Dimensions:','31 × 25 × 21 in','page1'),('color','Color:','Black','page1'),('maxuserweight','Max user weight','440 lb','page1')]
   notes.append('Product dimension units are not labelled in the PDF; no units inferred. Name follows the printed product title.')
  else:
   sheet,ev,score=match_sheet(sheets,sku);p=pairs(sheet);namepair=find(p,['item name','product name']);name=namepair[2]if namepair else None
   if sku=='SF-A023053':
    mis=find(p,['color']);assert mis and'ROW-N-RIDE'in mis[2];name=mis[2];p=[v for v in p if v!=mis];notes.append('Product title appears in the source Color cell; used as the name. Color is unavailable rather than treating a product title as a color.')
   if not name:raise ValueError('No descriptive product name: '+sku)
  cat=category(name,sku);p=pairs(sheet,cat,name)if not file.lower().endswith('.pdf')else p;vals={};evidence={};labels={}
  for key,aliases in ALIASES.items():
   pair=find(p,aliases)
   if pair:
    vals[key]=pair[2];labels[key]=pair[1];evidence[key]={'file':file,'sheet':sheet['name'],'cell':pair[3]}
  if file.lower().endswith('.pdf'):
   for k,label,v,cell in p:
    key={'productweight':'productWeight','shippingweight':'shippingWeight','keydimensions':'keyDimensions','shippingdimensions':'shippingDimensions','maxuserweight':'maxUserWeightLb'}.get(k,k)
    vals[key]=v;labels[key]=label;evidence[key]={'file':file,'sheet':'PDF','cell':'page1'}
  if sku=='NO. 086':
   for key in ['productWeight','shippingWeight','shippingDimensions']:
    if key in vals:vals[key]+=' (source packing basis is not verified for one pair)'
   notes.append('The sheet lists 80 pairs per carton and net 8.1 kg / 18 lb, gross 8.7 kg / 19.3 lb. These values are not verified as the weight of a single pair; no per-pair weight is inferred.')
  if sku=='NO. 074-M':
   for key,aliases in [('productWeight',['inner box NW']),('shippingWeight',['inner box GW']),('shippingDimensions',['product package dimension'])]:
    pair=find(p,aliases)
    if pair:vals[key]=pair[2];labels[key]=pair[1];evidence[key]={'file':file,'sheet':sheet['name'],'cell':pair[3]}
   notes.append('The sheet includes a six-piece master carton. Weight/shipping dimensions shown here use the explicitly labelled one-piece inner box, not the master carton.')
  if sku.startswith('NO.021-'):
   pair=find(p,['inner box dimension'])
   if pair:vals['shippingDimensions']=pair[2];evidence['shippingDimensions']={'file':file,'sheet':sheet['name'],'cell':pair[3]}
   notes.append('Net and gross weights are explicitly for one pair; shipping dimensions use the inner box. Wood-box case-pack measurements are excluded.')
  if vals.get('maxUserWeightLb')and N(vals['maxUserWeightLb'])in ['nolimit','unlimited']:
   vals.pop('maxUserWeightLb');notes.append('Source user capacity says no limit; no verified numeric capacity or unlimited-safe-use claim is inferred.')
  # Unit provenance comes from the field header as well as its answer cell.
  for key in ['productWeight','shippingWeight','flywheelWeight','keyDimensions','foldedDimensions','shippingDimensions','seatDimensions']:
   val=vals.get(key);label=labels.get(key,'')
   if not val or val=='Not applicable':continue
   if key.endswith('Weight')and re.fullmatch(r'\d+(?:\.\d+)?',val):
    if re.search(r'lbs?|pounds?',label,re.I):vals[key]+=' lb'
    elif re.search(r'kgs?|kilogram',label,re.I):vals[key]+=' kg'
   if key.endswith('Dimensions')and not re.search(r'cm|mm|inch|\d\s*in\b|\bft\b|feet|units',val,re.I):
    if re.search(r'inches|inch|\bin\b',label,re.I):vals[key]+=' in'
    elif re.search(r'\bcm\b',label,re.I):vals[key]+=' cm'
    else:notes.append('The source '+key+' field does not label measurement units; retained as written.')
  capacity=num_lb(vals.get('maxUserWeightLb'),labels.get('maxUserWeightLb',''))
  if capacity is None and vals.get('maxUserWeightLb')not in [None,'Not applicable']:notes.append('User capacity is retained as source text; no verified numeric lb capacity can be parsed.')
  drives=[vals.get(k)for k in ['driveResistanceSystem','resistanceType']if vals.get(k)not in [None,'Not applicable']];drive=' / '.join(dict.fromkeys(drives))or None
  levels=vals.get('speedResistanceLevels');levels=None if levels=='Not applicable'else levels
  motion=vals.get('stride')if cat=='Ellipticals'else vals.get('stepHeight')if cat=='Steppers'else vals.get('inclineStrideMotion')
  dims=vals.get('keyDimensions');dims=None if dims=='Not applicable'else dims
  comparison={'driveResistanceSystem':drive,'speedResistanceLevels':levels,'inclineStrideMotion':motion,'maxUserWeightLb':capacity,'keyDimensions':dims,'workoutAreaWidthIn':None,'workoutAreaLengthIn':None,'source':'V3 spec sheet: '+file,'portfolioCategory':cat,'dimensionOrder':'Source dimensions; order and units are retained as written.'}
  if sku=='SF-B1851':notes.append('Unrelated filled treadmill and rower reference subsections in this bike sheet are excluded. No treadmill speed, incline or running-belt measurements are assigned to this bike.')
  # Serialised values are strings. Cell evidence uses compact public references.
  spec={'version':1,'values':vals,'sources':[file],'evidence':{k:v['file']+' / '+v['sheet']+' / '+v['cell']for k,v in evidence.items()},'notes':notes}
  id='off-sunny-'+re.sub('[^a-z0-9]+','-',sku.lower()).strip('-');assert MODEL(sku)not in existing,sku;existing.add(MODEL(sku))
  rec={'id':id,'sku':sku,'name':name,'category':cat,'catalogSource':'off-sunny-web','sourceFile':file,'importBatch':'v3-batch-3','price':None,'priceChecked':True,'url':'','imageUrl':'','imageAssetId':None,'photoChecked':False,'photoMasks':None,'specDetails':spec,'productSpecs':comparison,'resourceLinks':{'manualUrl':None,'assemblyUrl':None,'manualPage':None,'assemblyPage':None,'checkedAt':None},'createdAt':'2026-11-06T00:00:00Z','updatedAt':'2026-11-06T00:00:00Z'};out.append(rec)
  audit.append({'id':id,'model':sku,'file':file,'sha256':hashlib.sha256((a.source/file).read_bytes()).hexdigest(),'sheet':sheet['name'],'modelEvidence':ev,'name':name,'category':cat,'fieldsFilled':len(vals),'notes':notes})
 assert len(out)==100 and len({r['id']for r in out})==100
 a.output.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');(ROOT/'data/off-sunny-web/batch-three-sources.json').write_text(json.dumps({'source':'Sorted Master SPEC SHEET - V3','importedAt':'2026-11-06','importedModels':100,'sourceFiles':len({r['file']for r in audit}),'records':audit},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print('Prepared',len(out),'models;',len({r['sourceFile']for r in out}),'files')
 for r in out:print(r['sku'],'|',r['name'],'|',r['category'],'|',len(r['specDetails']['values']))
if __name__=='__main__':main()
